const vals = wb.getRange('Sheet1!A1:A5002').getValues().map(r=>r[0]);
const nonStr = vals.filter(v=>typeof v!=='string').length;
const norm = vals.map(v=>String(v));
const upper = new Map(); const dup=[];
for (const w of norm){const u=w.toUpperCase(); if(upper.has(u)) dup.push(w); else upper.set(u,w);}
const odd = norm.filter(w=>w!==w.trim()||w!==w.toUpperCase()||!/^[A-Z]+$/.test(w)).slice(0,20);
const pairs=[];
for (const w of norm){const u=w.toUpperCase(); if(!u.includes('S')) continue;
 for(const v of 'AEIOU'){const t=u.replaceAll('S',v); if(upper.has(t)) pairs.push([w,upper.get(t),v]);}}
log({nonStr,dup:dup.length,odd,count:pairs.length, lens:[...new Set(norm.map(w=>w.length))]});
const multi=pairs.filter(p=>(p[0].match(/S/gi)||[]).length>1);
log(JSON.stringify(multi));
log(pairs.map(p=>p.join(' ')).join('\n'));
log(wb.getRange('Sheet1!G1:H1').getValues(), wb.getRange('Sheet1!G1:H5002').getCounts?.());
log(norm.includes('KAGOULE'),norm.includes('KAGOULS'))

